        val at = pointOnCircle(center, radius + opts.fontSize * 1.2, angles[i])
        val dx = at.x - center.x
        val align = if (Math.abs(dx) < 1.0) "middle" else if (dx > 0.0) "start" else "end"
        out.add(PyreonDrawCmd(kind = "text", fill = opts.labelColor, text = axes[i].label, at = at, size = opts.fontSize, align = align, baseline = "middle"))
      }
    }
    return out
  }

fun withAlpha(color: String, alpha: Double): String {
    val a = Math.max(0.0, Math.min(1.0, alpha))
    if (!color.startsWith("#")) {
      return color
    }
    val hex = color.drop(1)
    val code = fun(c: Double): Double {
      if (c >= 48.0 && c <= 57.0) {
        return c - 48.0
      }
      if (c >= 97.0 && c <= 102.0) {
        return c - 87.0
      }
      if (c >= 65.0 && c <= 70.0) {
        return c - 55.0
      }
      return 0.0
    }
    val pair = { at: Double -> code(hex[(at).toInt()].code.toDouble()) * 16.0 + code(hex[(at + 1).toInt()].code.toDouble()) }
    val single = { at: Double -> code(hex[(at).toInt()].code.toDouble()) * 17.0 }
    if (hex.length == 3) {
      return "rgba(${single(0.0)}, ${single(1.0)}, ${single(2.0)}, ${a})"
    }
    if (hex.length == 6) {
      return "rgba(${pair(0.0)}, ${pair(2.0)}, ${pair(4.0)}, ${a})"
    }
    return color
  }

fun computeLayout(cfg: LayoutConfig, measure: (String, Double) -> Double): PlotLayout {
    val padTop = 8.0
    val padRight = 12.0
    val labelGap = 6.0
    val tickLen = 4.0
    val provisionalLabels = if (cfg.horizontal == true) if (cfg.showYAxis) cfg.categories else listOf() else if (cfg.showYAxis) makeTicks(cfg.yDomain, cfg.height, 0.0, cfg.yTickCount, cfg.yFormat).map({ t -> t.label }) else listOf()
    var widest = 0.0
    for (label in provisionalLabels) {
      val w = measure(label, cfg.fontSize)
      if (w > widest) {
        widest = w
      }
    }
    val left = if (cfg.showYAxis) widest + labelGap + tickLen else 0.0
    val bottom = if (cfg.showXAxis) cfg.fontSize + labelGap + tickLen else 0.0
    val y2dom = (cfg.y2Domain ?: Domain(min = 0.0, max = 1.0))
    val hasY2 = cfg.y2Domain != null && cfg.horizontal != true && cfg.showYAxis
    var widest2 = 0.0
    if (hasY2) {
      for (label in makeTicks(y2dom, cfg.height, 0.0, cfg.yTickCount, cfg.y2Format).map({ t -> t.label })) {
        val w = measure(label, cfg.fontSize)
        if (w > widest2) {
          widest2 = w
        }
      }
    }
    val right = if (hasY2) widest2 + labelGap + tickLen else padRight
    val plot = PyreonChartRect(x = left, y = padTop, w = Math.max(0.0, cfg.width - left - right), h = Math.max(0.0, cfg.height - padTop - bottom))
    if (cfg.horizontal == true) {
      val yTicks = if (cfg.showYAxis) bandTicksY(cfg.categories, plot) else listOf()
      val xTicks = if (cfg.showXAxis) makeTicks(cfg.yDomain, plot.x, plot.x + plot.w, cfg.yTickCount, cfg.yFormat) else listOf()
      return PlotLayout(plot = plot, xTicks = xTicks, yTicks = yTicks, y2Ticks = listOf(), xDomainUsed = cfg.xDomain)
    }
    val yTicks = if (cfg.showYAxis) makeTicks(cfg.yDomain, plot.y + plot.h, plot.y, cfg.yTickCount, cfg.yFormat) else listOf()
    val xTicks = if (cfg.showXAxis) if (cfg.categories.length > 0) bandTicks(cfg.categories, plot) else if (cfg.xTime == true) timeTicks(cfg.xDomain, plot.x, plot.x + plot.w, cfg.xTickCount, cfg.xFormat) else makeTicks(cfg.xDomain, plot.x, plot.x + plot.w, cfg.xTickCount, cfg.xFormat) else listOf()
    val y2Ticks = if (hasY2) makeTicks(y2dom, plot.y + plot.h, plot.y, cfg.yTickCount, cfg.y2Format) else listOf()
    return PlotLayout(plot = plot, xTicks = xTicks, yTicks = yTicks, y2Ticks = y2Ticks, xDomainUsed = cfg.xDomain)
  }

fun bandTicksY(categories: List<String>, plot: PyreonChartRect): List<Tick> {
    val n = categories.length
    val out: MutableList<Tick> = mutableListOf()
    if (n == 0) {
      return out
    }
    val bh = (plot.h).toDouble() / (n).toDouble()
    for (i in 0 until n) {
      out.add(Tick(value = (i).toDouble(), pos = plot.y + bh * (i + 0.5), label = categories[i]))
    }
    return out
  }

fun bandTicks(categories: List<String>, plot: PyreonChartRect): List<Tick> {
    val n = categories.length
    val out: MutableList<Tick> = mutableListOf()
    if (n == 0) {
      return out
    }
    val bw = (plot.w).toDouble() / (n).toDouble()
    for (i in 0 until n) {
      out.add(Tick(value = (i).toDouble(), pos = plot.x + bw * (i + 0.5), label = categories[i]))
    }
    return out
  }

fun layoutBars(values: List<Double>, plot: PyreonChartRect, yDomain: Domain, gapRatio: Double): List<PyreonChartRect> {
    val n = values.length
    val out: MutableList<PyreonChartRect> = mutableListOf()
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.w).toDouble() / (n).toDouble()
    val bw = band * (1.0 - ratio)
    val zero = if (yDomain.min < 0.0 && yDomain.max > 0.0) 0.0 else yDomain.min
    val zeroY = scaleLinear(yDomain, plot.y + plot.h, plot.y, zero)
    for (i in 0 until n) {
      val v = values[i]
      val vy = scaleLinear(yDomain, plot.y + plot.h, plot.y, v)
      val top = if (vy < zeroY) vy else zeroY
      val h = Math.abs(zeroY - vy)
      out.add(PyreonChartRect(x = plot.x + band * i + ((band - bw)).toDouble() / (2.0).toDouble(), y = top, w = bw, h = h))
    }
    return out
  }

fun layoutSeriesPoints(values: List<Double>, plot: PyreonChartRect, yDomain: Domain): List<PyreonChartPt> {
    val n = values.length
    val out: MutableList<PyreonChartPt> = mutableListOf()
    if (n == 0) {
      return out
    }
    if (n == 1) {
      out.add(PyreonChartPt(x = plot.x + (plot.w).toDouble() / (2.0).toDouble(), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, values[0])))
      return out
    }
    for (i in 0 until n) {
      out.add(PyreonChartPt(x = plot.x + ((i).toDouble() / ((n - 1)).toDouble()) * plot.w, y = scaleLinear(yDomain, plot.y + plot.h, plot.y, values[i])))
    }
    return out
  }

fun layoutSeriesPointsAt(values: List<Double>, xs: List<Double>, plot: PyreonChartRect, yDomain: Domain, xDomain: Domain): List<PyreonChartPt> {
    val n = Math.min(values.length, xs.length)
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (i in 0 until n) {
      out.add(PyreonChartPt(x = scaleLinear(xDomain, plot.x, plot.x + plot.w, xs[i]), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, values[i])))
    }
    return out
  }

fun layoutBarsH(values: List<Double>, plot: PyreonChartRect, vDomain: Domain, gapRatio: Double): List<PyreonChartRect> {
    val n = values.length
    val out: MutableList<PyreonChartRect> = mutableListOf()
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.h).toDouble() / (n).toDouble()
    val bh = band * (1.0 - ratio)
    val zero = if (vDomain.min < 0.0 && vDomain.max > 0.0) 0.0 else vDomain.min
    val zeroX = scaleLinear(vDomain, plot.x, plot.x + plot.w, zero)
    for (i in 0 until n) {
      val v = values[i]
      val vx = scaleLinear(vDomain, plot.x, plot.x + plot.w, v)
      val left = if (vx < zeroX) vx else zeroX
      out.add(PyreonChartRect(x = left, y = plot.y + band * i + ((band - bh)).toDouble() / (2.0).toDouble(), w = (Math.abs(vx - zeroX)).toDouble(), h = bh))
    }
    return out
  }

fun hitBar(bars: List<PyreonChartRect>, px: Double, py: Double): Int {
    for (i in 0 until bars.length) {
      val b = bars[i]
      if (px >= b.x && px <= b.x + b.w && py >= b.y && py <= b.y + b.h) {
        return i
      }
    }
    return -1
  }

fun hitNearestX(points: List<PyreonChartPt>, px: Double): Int {
    if (points.length == 0) {
      return -1
    }
    var best = 0
    var bestD = Math.abs(points[0].x - px)
    for (i in 1 until points.length) {
      val d = Math.abs(points[i].x - px)
      if (d < bestD) {
        bestD = d
        best = i
      }
    }
    return best
  }

fun layoutStackedBars(seriesValues: List<List<Double>>, plot: PyreonChartRect, yDomain: Domain, gapRatio: Double): List<StackSegment> {
    val out: MutableList<StackSegment> = mutableListOf()
    if (seriesValues.length == 0) {
      return out
    }
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.w).toDouble() / (n).toDouble()
    val bw = band * (1.0 - ratio)
    for (i in 0 until n) {
      var acc = 0.0
      for (s in 0 until seriesValues.length) {
        val v = (seriesValues[s][i] ?: 0.0)
        if (v <= 0.0) {
          continue
        }
        val yTop = scaleLinear(yDomain, plot.y + plot.h, plot.y, acc + v)
        val yBot = scaleLinear(yDomain, plot.y + plot.h, plot.y, acc)
        out.add(StackSegment(rect = PyreonChartRect(x = plot.x + band * i + ((band - bw)).toDouble() / (2.0).toDouble(), y = yTop, w = bw, h = (Math.abs(yBot - yTop)).toDouble()), seriesIndex = s, datumIndex = i, value = v))
        acc = acc + v
      }
    }
    return out
  }

fun stackHasNegatives(seriesValues: List<List<Double>>): Boolean {
    for (s in seriesValues) {
      for (v in s) {
        if (v < 0.0) {
          return true
        }
      }
    }
    return false
  }

fun stackedExtent(seriesValues: List<List<Double>>): Domain {
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    var max = 0.0
    for (i in 0 until n) {
      var sum = 0.0
      for (s in seriesValues) {
        val v = (s[i] ?: 0.0)
        if (v > 0.0) {
          sum = sum + v
        }
      }
      if (sum > max) {
        max = sum
      }
    }
    return Domain(min = 0.0, max = if (max == 0.0) 1.0 else max)
  }

fun layoutGroupedBars(seriesValues: List<List<Double>>, plot: PyreonChartRect, yDomain: Domain, gapRatio: Double): List<StackSegment> {
    val out: MutableList<StackSegment> = mutableListOf()
    val k = seriesValues.length
    if (k == 0) {
      return out
    }
    var n = 0
    for (s in seriesValues) {
      if (s.length > n) {
        n = s.length
      }
    }
    if (n == 0) {
      return out
    }
    val ratio = if (gapRatio < 0.0) 0.0 else if (gapRatio > 0.9) 0.9 else gapRatio
    val band = (plot.w).toDouble() / (n).toDouble()
    val groupW = band * (1.0 - ratio)
    val barW = (groupW).toDouble() / (k).toDouble()
    val zero = if (yDomain.min < 0.0 && yDomain.max > 0.0) 0.0 else yDomain.min
    val zeroY = scaleLinear(yDomain, plot.y + plot.h, plot.y, zero)
    for (i in 0 until n) {
      val gx = plot.x + band * i + ((band - groupW)).toDouble() / (2.0).toDouble()
      for (s in 0 until k) {
        val v = (seriesValues[s][i] ?: 0.0)
        val vy = scaleLinear(yDomain, plot.y + plot.h, plot.y, v)
        out.add(StackSegment(rect = PyreonChartRect(x = gx + barW * s, y = if (vy < zeroY) vy else zeroY, w = barW, h = (Math.abs(zeroY - vy)).toDouble()), seriesIndex = s, datumIndex = i, value = v))
      }
    }
    return out
  }

fun layoutScatter(xs: List<Double>, ys: List<Double>, plot: PyreonChartRect, xDomain: Domain, yDomain: Domain): List<PyreonChartPt> {
    val n = Math.min(xs.length, ys.length)
    val out: MutableList<PyreonChartPt> = mutableListOf()
    for (i in 0 until n) {
      out.add(PyreonChartPt(x = scaleLinear(xDomain, plot.x, plot.x + plot.w, xs[i]), y = scaleLinear(yDomain, plot.y + plot.h, plot.y, ys[i])))
    }
    return out
  }

fun resolveYDomain(spec: ChartSpec): Domain = (spec.yDomain ?: deriveOver(leftAxisSeries(spec)))

fun resolveY2Domain(spec: ChartSpec): Domain = (spec.y2Domain ?: deriveOver(rightAxisSeries(spec)))

fun seriesOnRightAxis(s: Series, spec: ChartSpec): Boolean {
    if (spec.horizontal == true) {
      return false
    }
    if (s.kind == "stacked" || s.kind == "grouped") {
      return false
    }
    if (s.axis != "right") {
      return false
    }
    var hasLeft = false
    for (q in spec.series) {
      val qRight = q.axis == "right" && q.kind != "stacked" && q.kind != "grouped"
      if (!qRight) {
        hasLeft = true
      }
    }
    return hasLeft
  }

fun hasRightAxis(spec: ChartSpec): Boolean {
    for (s in spec.series) {
      if (seriesOnRightAxis(s, spec)) {
        return true
      }
    }
    return false
  }

fun leftAxisSeries(spec: ChartSpec): List<Series> = spec.series.filter({ s -> !seriesOnRightAxis(s, spec) })

fun rightAxisSeries(spec: ChartSpec): List<Series> = spec.series.filter({ s -> seriesOnRightAxis(s, spec) })

fun deriveOver(series: List<Series>): Domain {
    val stacked = series.filter({ s -> s.kind == "stacked" })
    if (stacked.length > 0) {
      val e = stackedExtent(stacked.map({ s -> s.values }))
      val others: MutableList<Double> = mutableListOf()
      for (s in series) {
        if (s.kind != "stacked") {
          for (v in s.values) {
            others.add(v)
          }
        }
      }
      val max = if (others.length > 0) Math.max(e.max, extent(others).max) else e.max
      return niceDomain(Domain(min = 0.0, max = max), 5.0)
    }
    val all: MutableList<Double> = mutableListOf()
    var hasBars = false
    for (s in series) {
      if (s.kind == "bars" || s.kind == "area" || s.kind == "grouped") {
        hasBars = true
      }
      for (v in s.values) {
        all.add(v)
      }
    }
    val e = extent(all)
    val withZero = if (hasBars) Domain(min = if (e.min > 0.0) 0.0 else e.min, max = if (e.max < 0.0) 0.0 else e.max) else e
    return niceDomain(withZero, 5.0)
  }

fun seriesMaxLength(series: List<Series>): Int {
    var n = 0
    for (s in series) {
      if (s.values.length > n) {
        n = s.values.length
      }
    }
    return n
  }

fun layoutChart(spec: ChartSpec, measure: (String, Double) -> Double): PlotLayout {
    val n = seriesMaxLength(spec.series)
    val cfg = LayoutConfig(width = spec.width, height = spec.height, xDomain = if (((spec.xValues ?: listOf())).length > 0) extent((spec.xValues ?: listOf())) else Domain(min = 0.0, max = if (n > 1) (n - 1).toDouble() else 1.0), yDomain = resolveYDomain(spec), categories = spec.categories, fontSize = spec.theme.fontSize, xTickCount = 5.0, yTickCount = 5.0, showXAxis = spec.showXAxis, showYAxis = spec.showYAxis, yFormat = spec.yFormat, xFormat = spec.xFormat, xTime = spec.xTime == true, y2Domain = if (hasRightAxis(spec)) resolveY2Domain(spec) else null, y2Format = spec.y2Format, horizontal = spec.horizontal == true)
    return computeLayout(cfg, measure)
  }

fun renderChart(spec: ChartSpec, measure: (String, Double) -> Double): List<PyreonDrawCmd> {
    val yDomain = resolveYDomain(spec)
    val useY2 = hasRightAxis(spec)
    val y2Domain = if (useY2) resolveY2Domain(spec) else yDomain
    val l = layoutChart(spec, measure)
    val plot = l.plot
    val t = spec.theme
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val rawProgress = (spec.progress ?: 1.0)
    val progress = if (rawProgress < 0.0) 0.0 else if (rawProgress > 1.0) 1.0 else rawProgress
    val growRect = fun(r: PyreonChartRect, dom: Domain): PyreonChartRect {
      if (progress >= 1.0) {
        return r
      }
      val zeroY = scaleLinear(dom, plot.y + plot.h, plot.y, if (dom.min < 0.0 && dom.max > 0.0) 0.0 else dom.min)
      val h = r.h * progress
      val top = if (r.y + r.h <= zeroY + 0.5) zeroY - h else zeroY
      return PyreonChartRect(x = r.x, y = top, w = r.w, h = h)
    }
    val growRectH = fun(r: PyreonChartRect): PyreonChartRect {
      if (progress >= 1.0) {
        return r
      }
      val zeroX = scaleLinear(yDomain, plot.x, plot.x + plot.w, if (yDomain.min < 0.0 && yDomain.max > 0.0) 0.0 else yDomain.min)
      val w = r.w * progress
      val left = if (r.x >= zeroX - 0.5) zeroX else zeroX - w
      return PyreonChartRect(x = left, y = r.y, w = w, h = r.h)
    }
    val reveal = fun(pts: List<PyreonChartPt>): List<PyreonChartPt> {
      if (progress >= 1.0 || pts.length < 2) {
        return pts
      }
      val span = pts.length - 1
      val cut = span * progress
      val whole = Math.floor(cut)
      val outPts: MutableList<PyreonChartPt> = mutableListOf()
      for (i in 0..Math.floor(whole).toInt()) {
        outPts.add(pts[i])
      }
      val frac = cut - whole
      if (frac > 0.0 && whole + 1 < pts.length) {
        val a = pts[(whole).toInt()]
        val b = pts[(whole + 1).toInt()]
        outPts.add(PyreonChartPt(x = a.x + (b.x - a.x) * frac, y = a.y + (b.y - a.y) * frac))
      }
      return outPts
    }
    if (spec.showGrid) {
      if (spec.horizontal == true) {
        for (tick in l.xTicks) {
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = tick.pos, y = plot.y), to = PyreonChartPt(x = tick.pos, y = plot.y + plot.h), stroke = t.grid, width = 1.0))
        }
      } else {
        for (tick in l.yTicks) {
          out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = tick.pos), to = PyreonChartPt(x = plot.x + plot.w, y = tick.pos), stroke = t.grid, width = 1.0))
        }
      }
    }
    if (spec.showYAxis) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = plot.y), to = PyreonChartPt(x = plot.x, y = plot.y + plot.h), stroke = t.axis, width = 1.0))
    }
    if (spec.showXAxis) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = plot.y + plot.h), to = PyreonChartPt(x = plot.x + plot.w, y = plot.y + plot.h), stroke = t.axis, width = 1.0))
    }
    if (spec.showYAxis && useY2) {
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x + plot.w, y = plot.y), to = PyreonChartPt(x = plot.x + plot.w, y = plot.y + plot.h), stroke = t.axis, width = 1.0))
    }
    val notes = (spec.annotations ?: listOf())
    for (a in notes) {
      val yFrom = (a.yFrom ?: 0.0)
      val yTo = (a.yTo ?: 0.0)
      if (a.yFrom != null && a.yTo != null) {
        val y1 = scaleLinear(yDomain, plot.y + plot.h, plot.y, yFrom)
        val y2 = scaleLinear(yDomain, plot.y + plot.h, plot.y, yTo)
        val top = if (y1 < y2) y1 else y2
        out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = plot.x, y = top, w = plot.w, h = (Math.abs(y2 - y1)).toDouble()), fill = withAlpha((a.color ?: t.axis), 0.12)))
      }
    }
    for (a in notes) {
      val ay = (a.y ?: 0.0)
      if (a.y != null) {
        val yPos = scaleLinear(yDomain, plot.y + plot.h, plot.y, ay)
        out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = plot.x, y = yPos), to = PyreonChartPt(x = plot.x + plot.w, y = yPos), stroke = (a.color ?: t.axis), width = 1.0, dash = listOf(4.0, 4.0)))
        val yLabel = (a.label ?: "")
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = yLabel, at = PyreonChartPt(x = plot.x + plot.w, y = yPos - 4.0), size = t.fontSize, align = "end", baseline = "bottom"))
        }
      }
      val ax = (a.x ?: 0.0)
      if (a.x != null) {
        val xPos = scaleLinear(l.xDomainUsed, plot.x, plot.x + plot.w, ax)
        out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = xPos, y = plot.y), to = PyreonChartPt(x = xPos, y = plot.y + plot.h), stroke = (a.color ?: t.axis), width = 1.0, dash = listOf(4.0, 4.0)))
        val xLabel = (a.label ?: "")
        if (a.label != null) {
          out.add(PyreonDrawCmd(kind = "text", fill = (a.color ?: t.label), text = xLabel, at = PyreonChartPt(x = xPos + 4.0, y = plot.y), size = t.fontSize, align = "start", baseline = "top"))
        }
      }
    }
    val stackedSeries = if (spec.horizontal == true) listOf() else spec.series.filter({ s -> s.kind == "stacked" })
    if (stackedSeries.length > 0) {
      for (seg in layoutStackedBars(stackedSeries.map({ s -> s.values }), plot, yDomain, 0.25)) {
        out.add(PyreonDrawCmd(kind = "rect", rect = growRect(seg.rect, yDomain), fill = stackedSeries[seg.seriesIndex].color))
      }
    }
    val groupedSeries = if (spec.horizontal == true) listOf() else spec.series.filter({ s -> s.kind == "grouped" })
    if (groupedSeries.length > 0) {
      for (seg in layoutGroupedBars(groupedSeries.map({ s -> s.values }), plot, yDomain, 0.25)) {
        out.add(PyreonDrawCmd(kind = "rect", rect = growRect(seg.rect, yDomain), fill = groupedSeries[seg.seriesIndex].color))
      }
    }
    for (s in spec.series) {
      if (s.kind == "stacked" || s.kind == "grouped") {
        continue
      }
      val xs = (spec.xValues ?: listOf())
      val sDomain = if (seriesOnRightAxis(s, spec)) y2Domain else yDomain
      val place = { values: List<Double> -> if (xs.length > 0) layoutSeriesPointsAt(values, xs, plot, sDomain, l.xDomainUsed) else layoutSeriesPoints(values, plot, sDomain) }
      val curveFn = (s.curve ?: ({ q -> q }))
      val shape = { pts: List<PyreonChartPt> -> curveFn(pts) }
      if (spec.horizontal == true) {
        if (s.kind != "bars") {
          continue
        }
        val rects = layoutBarsH(s.values, plot, yDomain, 0.25)
        for (r in rects) {
          out.add(PyreonDrawCmd(kind = "rect", rect = growRectH(r), fill = s.color))
        }
        if (s.showValues == true && progress >= 1.0) {
          val fmt = (spec.yFormat ?: ::plain)
          for (i in 0 until rects.length) {
            val r = rects[i]
            val v = s.values[i]
            out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = fmt(v), at = PyreonChartPt(x = if (v < 0.0) r.x - 4.0 else r.x + r.w + 4.0, y = r.y + (r.h).toDouble() / (2.0).toDouble()), size = t.fontSize, align = if (v < 0.0) "end" else "start", baseline = "middle"))
          }
        }
        continue
      }
      if (s.kind == "bars") {
        val rects = layoutBars(s.values, plot, sDomain, 0.25)
        for (r in rects) {
          out.add(PyreonDrawCmd(kind = "rect", rect = growRect(r, sDomain), fill = s.color))
        }
        if (s.showValues == true && progress >= 1.0) {
          val fmt = (spec.yFormat ?: ::plain)
          for (i in 0 until rects.length) {
            val r = rects[i]
            val v = s.values[i]
            out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = fmt(v), at = PyreonChartPt(x = r.x + (r.w).toDouble() / (2.0).toDouble(), y = if (v < 0.0) r.y + r.h + 4.0 else r.y - 4.0), size = t.fontSize, align = "middle", baseline = if (v < 0.0) "top" else "bottom"))
          }
        }
      } else {
        if (s.kind == "line") {
          val pts = reveal(shape(place(s.values)))
          if (pts.length > 1) {
            out.add(PyreonDrawCmd(kind = "polyline", stroke = s.color, width = s.width, points = pts))
          }
        } else {
          if (s.kind == "area") {
            val pts = reveal(shape(place(s.values)))
            if (pts.length > 1) {
              val poly: MutableList<PyreonChartPt> = mutableListOf()
              for (p in pts) {
                poly.add(p)
              }
              poly.add(PyreonChartPt(x = pts[pts.length - 1].x, y = plot.y + plot.h))
              poly.add(PyreonChartPt(x = pts[0].x, y = plot.y + plot.h))
              out.add(PyreonDrawCmd(kind = "polygon", fill = s.color, points = poly))
            }
          } else {
            val pts = place(s.values)
            val radii = (s.radii ?: listOf())
            for (i in 0 until pts.length) {
              val fullR = if (radii.length > 0) (radii[i] ?: s.radius) else s.radius
              out.add(PyreonDrawCmd(kind = "circle", fill = s.color, center = pts[i], radius = fullR * progress))
            }
          }
        }
      }
    }
    val markers = (spec.markers ?: listOf())
    for (m in markers) {
      if (spec.horizontal == true) {
        continue
      }
      val rawSeriesIndex = (m.seriesIndex ?: 0.0)
      val s = spec.series[(Math.floor(rawSeriesIndex)).toInt()]
      if (s == null) {
        continue
      }
      if (s.kind == "stacked" || s.kind == "grouped") {
        continue
      }
      val n = s.values.length
      if (n == 0) {
        continue
      }
      var idx = -1
      if (m.at == "max") {
        idx = 0
        for (i in 1 until n) {
          if (s.values[i] > s.values[idx]) {
            idx = i
          }
        }
      } else {
        if (m.at == "min") {
          idx = 0
          for (i in 1 until n) {
            if (s.values[i] < s.values[idx]) {
              idx = i
            }
          }
        } else {
          val rawAt = (m.atIndex ?: -1.0)
          if (m.atIndex != null) {
            var jf = 0.0
            for (j in 0 until n) {
              if (jf <= rawAt) {
                idx = j
              }
              jf = jf + 1.0
            }
            if (idx < 0) {
              idx = 0
            }
          }
        }
      }
      if (idx < 0) {
        continue
      }
      val mDomain = if (seriesOnRightAxis(s, spec)) y2Domain else yDomain
      val xsM = (spec.xValues ?: listOf())
      val pts = if (xsM.length > 0) layoutSeriesPointsAt(s.values, xsM, plot, mDomain, l.xDomainUsed) else layoutSeriesPoints(s.values, plot, mDomain)
      val p = pts[idx]
      if (p == null) {
        continue
      }
      val mColor = (m.color ?: s.color)
      out.add(PyreonDrawCmd(kind = "circle", fill = mColor, center = p, radius = ((m.radius ?: 4.0)) * progress))
      val mLabel = (m.label ?: "")
      if (m.label != null && progress >= 1.0) {
        out.add(PyreonDrawCmd(kind = "text", fill = mColor, text = mLabel, at = PyreonChartPt(x = p.x, y = p.y - ((m.radius ?: 4.0)) - 4.0), size = t.fontSize, align = "middle", baseline = "bottom"))
      }
    }
    for (tick in l.yTicks) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = plot.x - 6.0, y = tick.pos), size = t.fontSize, align = "end", baseline = "middle"))
    }
    for (tick in l.y2Ticks) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = plot.x + plot.w + 6.0, y = tick.pos), size = t.fontSize, align = "start", baseline = "middle"))
    }
    for (tick in l.xTicks) {
      out.add(PyreonDrawCmd(kind = "text", fill = t.label, text = tick.label, at = PyreonChartPt(x = tick.pos, y = plot.y + plot.h + 6.0), size = t.fontSize, align = "middle", baseline = "top"))
    }
    return out
  }

fun barsFor(spec: ChartSpec, index: Int, measure: (String, Double) -> Double): List<PyreonChartRect> {
    val s = spec.series[index]
    if (s == null || s.kind != "bars") {
      return listOf()
    }
    val dom = if (seriesOnRightAxis(s, spec)) resolveY2Domain(spec) else resolveYDomain(spec)
    return layoutBars(s.values, layoutChart(spec, measure).plot, dom, 0.25)
  }

fun stackedHitAt(spec: ChartSpec, measure: (String, Double) -> Double, px: Double, py: Double): Int {
    if (spec.horizontal == true) {
      return -1
    }
    val plot = layoutChart(spec, measure).plot
    val yDomain = resolveYDomain(spec)
    for (kind in listOf("stacked", "grouped")) {
      val series = spec.series.filter({ s -> s.kind == kind })
      if (series.length == 0) {
        continue
      }
      val values = series.map({ s -> s.values })
      val segs = if (kind == "stacked") layoutStackedBars(values, plot, yDomain, 0.25) else layoutGroupedBars(values, plot, yDomain, 0.25)
      for (seg in segs) {
        val r = seg.rect
        if (px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h) {
          return seg.datumIndex
        }
      }
    }
    return -1
  }

fun ohlcExtent(candles: List<Ohlc>): Domain {
    if (candles.length == 0) {
      return Domain(min = 0.0, max = 1.0)
    }
    var lo = candles[0].low
    var hi = candles[0].high
    for (c in candles) {
      if (c.low < lo) {
        lo = c.low
      }
      if (c.high > hi) {
        hi = c.high
      }
    }
    if (hi <= lo) {
      return Domain(min = lo - 1.0, max = lo + 1.0)
    }
    return Domain(min = lo, max = hi)
  }

fun renderCandles(candles: List<Ohlc>, plot: PyreonChartRect, domain: Domain, options: CandleOptions? = null): List<PyreonDrawCmd> {
    val up = (options?.upColor ?: "#15803d")
    val down = (options?.downColor ?: "#b42318")
    val rawRatio = (options?.widthRatio ?: 0.6)
    val ratio = if (rawRatio < 0.05) 0.05 else if (rawRatio > 0.9) 0.9 else rawRatio
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val n = candles.length
    if (n == 0) {
      return out
    }
    val band = (plot.w).toDouble() / (n).toDouble()
    val bw = band * ratio
    val yOf = { v: Double -> scaleLinear(domain, plot.y + plot.h, plot.y, v) }
    for (i in 0 until n) {
      val c = candles[i]
      val cx = plot.x + band * i + (band).toDouble() / (2.0).toDouble()
      val color = if (c.close >= c.open) up else down
      out.add(PyreonDrawCmd(kind = "line", from = PyreonChartPt(x = cx, y = yOf(c.high)), to = PyreonChartPt(x = cx, y = yOf(c.low)), stroke = color, width = 1.0))
      val yo = yOf(c.open)
      val yc = yOf(c.close)
      val top = if (yo < yc) yo else yc
      val h = Math.abs(yc - yo)
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = cx - (bw).toDouble() / (2.0).toDouble(), y = top, w = bw, h = if (h < 1.0) 1.0 else h), fill = color))
    }
    return out
  }

fun hitCandle(count: Int, plot: PyreonChartRect, px: Double, py: Double): Int {
    if (count <= 0) {
      return -1
    }
    if (px < plot.x || px > plot.x + plot.w) {
      return -1
    }
    if (py < plot.y || py > plot.y + plot.h) {
      return -1
    }
    val band = (plot.w).toDouble() / (count).toDouble()
    val target = ((px - plot.x)).toDouble() / (band).toDouble()
    var i = 0
    var jf = 0.0
    for (j in 0 until count) {
      if (jf <= target) {
        i = j
      }
      jf = jf + 1.0
    }
    return i
  }

fun buildHeatGrid(cols: List<String>, rows: List<String>, colOf: List<Double>, rowOf: List<Double>, values: List<Double>): HeatGrid {
    val byKey = mutableMapOf<String, Int>()
    val cells: MutableList<HeatCell> = mutableListOf()
    val n = Math.min(colOf.length, Math.min(rowOf.length, values.length))
    var minV = 0.0
    var maxV = 0.0
    var seen = false
    for (i in 0 until n) {
      val c = colOf[i]
      val r = rowOf[i]
      if (c < 0.0 || r < 0.0) {
        continue
      }
      val key = "${c}:${r}"
      val prior = byKey[key]
      val at = (prior ?: -1)
      if (prior == null) {
        byKey[key] = cells.length
        cells.add(HeatCell(col = c, row = r, value = values[i]))
      } else {
        cells[at].value = cells[at].value + values[i]
      }
    }
    for (cell in cells) {
      if (!seen) {
        minV = cell.value
        maxV = cell.value
        seen = true
      } else {
        if (cell.value < minV) {
          minV = cell.value
        }
        if (cell.value > maxV) {
          maxV = cell.value
        }
      }
    }
    return HeatGrid(cols = cols, rows = rows, cells = cells, min = minV, max = maxV)
  }

fun hexChannel(hex: String, at: Int): Double {
    val code = fun(ch: Double): Double {
      val c = ch
      if (c >= 48.0 && c <= 57.0) {
        return c - 48.0
      }
      if (c >= 97.0 && c <= 102.0) {
        return c - 87.0
      }
      if (c >= 65.0 && c <= 70.0) {
        return c - 55.0
      }
      return 0.0
    }
    if (hex.length < at + 2) {
      return 0.0
    }
    return code(hex[(at).toInt()].code.toDouble()) * 16.0 + code(hex[(at + 1).toInt()].code.toDouble())
  }

fun colorRamp(stops: List<String>): (Double) -> String {
    val rs: MutableList<Double> = mutableListOf()
    val gs: MutableList<Double> = mutableListOf()
    val bs: MutableList<Double> = mutableListOf()
    for (sHex in stops) {
      val off = if (sHex.startsWith("#")) 1 else 0
      rs.add(hexChannel(sHex, off))
      gs.add(hexChannel(sHex, off + 2))
      bs.add(hexChannel(sHex, off + 4))
    }
    var spanF = -1.0
    for (k in 0 until rs.length) {
      spanF = spanF + 1.0
    }
    return fun(t: Double): String {
      var result = "rgb(0, 0, 0)"
      if (rs.length == 1 || (rs.length > 1 && t <= 0.0)) {
        result = "rgb(${Math.round(rs[0])}, ${Math.round(gs[0])}, ${Math.round(bs[0])})"
      } else {
        if (rs.length > 1) {
          val clamped = if (t >= 1.0) 1.0 else t
          val pos = clamped * spanF
          var idx = 0
          var idxF = 0.0
          var jf = 1.0
          for (k in 1 until rs.length - 1) {
            if (jf <= pos) {
              idx = k
              idxF = jf
            }
            jf = jf + 1.0
          }
          val frac = pos - idxF
          val mix = { x: Double, y: Double -> Math.round(x + (y - x) * frac) }
          result = "rgb(${mix(rs[idx], rs[idx + 1])}, ${mix(gs[idx], gs[idx + 1])}, ${mix(bs[idx], bs[idx + 1])})"
        }
      }
      return result
    }
  }

fun renderHeat(options: HeatmapOptions): List<PyreonDrawCmd> {
    val grid = options.grid
    val plot = options.plot
    val ramp = colorRamp(options.stops)
    val gap = (options.gap ?: 1.0)
    val rawP = (options.progress ?: 1.0)
    val progress = if (rawP < 0.0) 0.0 else if (rawP > 1.0) 1.0 else rawP
    val out: MutableList<PyreonDrawCmd> = mutableListOf()
    val nc = grid.cols.length
    val nr = grid.rows.length
    if (nc == 0 || nr == 0) {
      return out
    }
    var ncF = 0.0
    for (k in 0 until nc) {
      ncF = ncF + 1.0
    }
    var nrF = 0.0
    for (k in 0 until nr) {
      nrF = nrF + 1.0
    }
    val cw = (plot.w).toDouble() / (nc).toDouble()
    val ch = (plot.h).toDouble() / (nr).toDouble()
    val span = grid.max - grid.min
    for (cell in grid.cells) {
      if (cell.col >= ncF || cell.row >= nrF) {
        continue
      }
      val t = if (span <= 0.0) 1.0 else ((cell.value - grid.min)).toDouble() / (span).toDouble()
      val fullW = cw - gap
      val fullH = ch - gap
      val w = fullW * progress
      val h = fullH * progress
      val x = plot.x + cell.col * cw + (gap).toDouble() / (2.0).toDouble() + ((fullW - w)).toDouble() / (2.0).toDouble()
      val y = plot.y + cell.row * ch + (gap).toDouble() / (2.0).toDouble() + ((fullH - h)).toDouble() / (2.0).toDouble()
      out.add(PyreonDrawCmd(kind = "rect", rect = PyreonChartRect(x = x, y = y, w = w, h = h), fill = ramp(t)))
    }
    return out
  }

fun hitHeatCell(grid: HeatGrid, plot: PyreonChartRect, gap: Double, px: Double, py: Double): Int {
    val nc = grid.cols.length
    val nr = grid.rows.length
    if (nc == 0 || nr == 0) {
      return -1
    }
    if (px < plot.x || px > plot.x + plot.w || py < plot.y || py > plot.y + plot.h) {
      return -1
    }
    val cw = (plot.w).toDouble() / (nc).toDouble()
    val ch = (plot.h).toDouble() / (nr).toDouble()
    val tCol = ((px - plot.x)).toDouble() / (cw).toDouble()
    val tRow = ((py - plot.y)).toDouble() / (ch).toDouble()
    var colF = 0.0
    var jf = 0.0
    for (j in 0 until nc) {
      if (jf <= tCol) {
        colF = jf
      }
      jf = jf + 1.0
    }
    var rowF = 0.0
    var kf = 0.0
    for (k in 0 until nr) {
      if (kf <= tRow) {
        rowF = kf
      }
      kf = kf + 1.0
    }
    val inX = px - (plot.x + colF * cw)
    val inY = py - (plot.y + rowF * ch)
    if (inX < (gap).toDouble() / (2.0).toDouble() || inX > cw - (gap).toDouble() / (2.0).toDouble()) {
      return -1
    }
    if (inY < (gap).toDouble() / (2.0).toDouble() || inY > ch - (gap).toDouble() / (2.0).toDouble()) {
      return -1
    }
    for (i in 0 until grid.cells.length) {
      val c = grid.cells[i]
      if (c.col == colF && c.row == rowF) {
        return i
      }
    }
    return -1
  }
